package com.franco.desco.adapter.out.sqlserver.campaign;import com.franco.desco.adapter.out.sqlserver.shared.*;import com.franco.desco.application.campaign.*;import com.franco.desco.application.campaign.port.out.CampaignPersistencePort;import com.franco.desco.application.shared.*;import com.franco.desco.application.shared.pagination.PageResult;import com.franco.desco.domain.campaign.CampaignModels;import org.springframework.jdbc.core.simple.SimpleJdbcCall;import org.springframework.stereotype.Component;import java.util.*;
@Component public class CampaignSqlServerAdapter implements CampaignPersistencePort{private final SqlServerPaExecutor e;private final PaPayloadFactory pf;private final SimpleJdbcCall list,get,create,update,activate,close,cancel;public CampaignSqlServerAdapter(SqlServerPaFactory f,SqlServerPaExecutor e,PaPayloadFactory pf){this.e=e;this.pf=pf;list=f.callWithResultSets("comercial","PA_CampaniaVenta_Sel_Listado","items");get=f.callWithResultSets("comercial","PA_CampaniaVenta_Sel_DetalleCompleto","header","participants","operations","prices");create=f.call("comercial","PA_CampaniaVenta_Ins_Registro");update=f.call("comercial","PA_CampaniaVenta_Upd_Registro");activate=f.call("comercial","PA_CampaniaVenta_Upd_Activar");close=f.call("comercial","PA_CampaniaVenta_Upd_Cerrar");cancel=f.call("comercial","PA_CampaniaVenta_Upd_Cancelar");}
 public PersistenceResult<PageResult<CampaignModels.Summary>>list(CampaignCommands.ListCampaigns c,SessionIdentity i,RequestMetadata m){var pg=c.page();var f=pg.filtros();var payload=pf.forQuery(i,m,map("filtros",map("estadoProceso",f==null?null:f.estadoProceso(),"asociacionId",f==null?null:f.asociacionId(),"empresaCompradoraId",f==null?null:f.empresaCompradoraId(),"fechaDesde",f==null?null:f.fechaDesde(),"fechaHasta",f==null?null:f.fechaHasta()),"paginacion",map("pagina",pg.pagina(),"tamano",pg.tamanio())));var out=e.executeJson(list,payload);return PaAdapterSupport.page(out,rows(out,"items"),pg.pagina(),pg.tamanio(),this::summary,"No se pudieron consultar las campañas.");}
 public PersistenceResult<CampaignModels.Detail>get(CampaignCommands.Get c,SessionIdentity i,RequestMetadata m){var out=e.executeJson(get,pf.forQuery(i,m,Map.of("campania",Map.of("campaniaVentaId",c.campaniaVentaId()))));if(!PaAdapterSupport.success(out))return PersistenceResult.error(PaAdapterSupport.message(out,"No se pudo consultar la campaña."));var h=one(out,"header");if(h==null)return PersistenceResult.error("La campaña seleccionada no está disponible.");return PersistenceResult.ok(PaAdapterSupport.message(out,"Campaña consultada correctamente."),new CampaignModels.Detail(summary(h),rows(out,"participants").stream().map(this::participant).toList(),rows(out,"operations").stream().map(this::operation).toList(),rows(out,"prices").stream().map(this::price).toList()));}
 public PersistenceResult<Long>create(CampaignCommands.Create c,SessionIdentity i,RequestMetadata m){var out=e.executeJson(create,pf.forWrite(i,m,c,Map.of("campania",map("asociacionId",c.asociacionId(),"empresaCompradoraId",c.empresaCompradoraId(),"codigo",c.codigo(),"nombre",c.nombre(),"fechaInicio",c.fechaInicio(),"fechaFin",c.fechaFin(),"observacion",c.observacion()))));return PaAdapterSupport.result(out,SqlValues.longValue(out,"nCampaniaVentaId"),"No se pudo crear la campaña.");}
 public PersistenceResult<Void>update(CampaignCommands.Update c,SessionIdentity i,RequestMetadata m){return mut(update,i,m,c,map("campaniaVentaId",c.campaniaVentaId(),"empresaCompradoraId",c.empresaCompradoraId(),"nombre",c.nombre(),"fechaInicio",c.fechaInicio(),"fechaFin",c.fechaFin(),"observacion",c.observacion()),"No se pudo actualizar la campaña.");}public PersistenceResult<Void>activate(CampaignCommands.Transition c,SessionIdentity i,RequestMetadata m){return mut(activate,i,m,c,map("campaniaVentaId",c.campaniaVentaId(),"motivo",c.motivo()),"No se pudo activar la campaña.");}public PersistenceResult<Void>close(CampaignCommands.Transition c,SessionIdentity i,RequestMetadata m){return mut(close,i,m,c,map("campaniaVentaId",c.campaniaVentaId(),"motivo",c.motivo()),"No se pudo cerrar la campaña.");}public PersistenceResult<Void>cancel(CampaignCommands.Transition c,SessionIdentity i,RequestMetadata m){return mut(cancel,i,m,c,map("campaniaVentaId",c.campaniaVentaId(),"motivo",c.motivo()),"No se pudo cancelar la campaña.");}
 private PersistenceResult<Void>mut(SimpleJdbcCall call,SessionIdentity i,RequestMetadata m,Object body,Map<String,Object>v,String f){return PaAdapterSupport.result(e.executeJson(call,pf.forWrite(i,m,body,Map.of("campania",v))),null,f);}private CampaignModels.Summary summary(Map<String,Object>r){return new CampaignModels.Summary(SqlValues.longValue(r,"campaniaVentaId"),SqlValues.string(r,"codigo"),SqlValues.string(r,"nombre"),SqlValues.localDate(r,"fechaInicio"),SqlValues.localDate(r,"fechaFin"),SqlValues.string(r,"estadoProceso"),SqlValues.longValue(r,"asociacionId"),SqlValues.string(r,"asociacion"),SqlValues.longValue(r,"empresaCompradoraId"),SqlValues.string(r,"comprador"),SqlValues.string(r,"observacion"),SqlValues.longValue(r,"participantesActivos"),SqlValues.longValue(r,"operativos"));}private CampaignModels.Participant participant(Map<String,Object>r){return new CampaignModels.Participant(SqlValues.longValue(r,"participacionId"),SqlValues.string(r,"estadoParticipacion"),SqlValues.longValue(r,"socioId"),SqlValues.string(r,"numeroDocumento"),SqlValues.string(r,"socioNombre"));}private CampaignModels.Operation operation(Map<String,Object>r){return new CampaignModels.Operation(SqlValues.longValue(r,"operativoVentaId"),SqlValues.string(r,"codigo"),SqlValues.instant(r,"fechaInicioProgramada"),SqlValues.instant(r,"fechaFinProgramada"),SqlValues.instant(r,"fechaInicioReal"),SqlValues.instant(r,"fechaFinReal"),SqlValues.intValue(r,"cantidadJabasRecibidas"),SqlValues.string(r,"estadoProceso"),SqlValues.string(r,"observacion"));}private CampaignModels.Price price(Map<String,Object>r){return new CampaignModels.Price(SqlValues.longValue(r,"precioComercialId"),SqlValues.longValue(r,"operativoVentaId"),SqlValues.intValue(r,"variedadPaltaId"),SqlValues.longValue(r,"condicionComercialId"),SqlValues.decimal(r,"precio"),SqlValues.string(r,"moneda"),SqlValues.string(r,"unidadMedida"),SqlValues.instant(r,"fechaVigenciaDesde"),SqlValues.instant(r,"fechaVigenciaHasta"),SqlValues.intValue(r,"version"));}private List<Map<String,Object>>rows(Map<String,Object>o,String k){return new PaResultSets(o).rows(k);}private Map<String,Object>one(Map<String,Object>o,String k){return new PaResultSets(o).one(k).orElse(null);}private static Map<String,Object>map(Object...v){Map<String,Object>m=new LinkedHashMap<>();for(int n=0;n<v.length;n+=2)if(v[n+1]!=null)m.put((String)v[n],v[n+1]);return m;}}
